<script>
import { api,money,date } from '../api'
export default {
 data:()=>({events:[],categories:[],filter:{query:'',categoryId:null,city:'',from:'',to:''},page:1,busy:false,error:'',next:false}),
 async mounted(){try{this.categories=await api('/catalog/categories')}catch(e){this.error=e.message}await this.search()},
 methods:{money,date,async search(reset=true){if(reset)this.page=1;this.busy=true;this.error='';try{const q=new URLSearchParams({page:this.page,pageSize:12});for(const [key,value]of Object.entries(this.filter))if(value!==null&&value!=='')q.set(key,key==='from'||key==='to'?value+'T'+(key==='to'?'23:59:59':'00:00:00')+'-05:00':value);this.events=await api('/catalog/events?'+q);this.next=this.events.length===12}catch(e){this.error=e.message;this.events=[]}finally{this.busy=false}},clear(){this.filter={query:'',categoryId:null,city:'',from:'',to:''};this.search()},async move(delta){this.page+=delta;await this.search(false)}}}
</script>
<template><q-page><section class="hero"><div class="hero-copy"><div class="eyebrow">TU CIUDAD TIENE MUCHO QUE CONTAR</div><h1>Sal de la rutina.<br><em>Encuentra tu próximo plan.</em></h1><p>Conciertos, talleres, ferias y experiencias locales.<br>Descubre lo que pasa cerca de ti.</p><div class="hero-chips"><span>Hecho en Perú</span><span>Experiencias para todos</span></div></div><div class="hero-art" aria-hidden="true"><span class="orbit one"></span><span class="orbit two"></span><div class="ticket-art"><small>LA MEJOR ENTRADA</small><strong>A un buen<br>recuerdo.</strong><div class="ticket-line"></div><span>ENCUENTRA · CONECTA · DISFRUTA</span></div><span class="star">✳</span></div></section>
 <main class="container"><q-form class="search-panel" @submit="search()"><q-input outlined v-model="filter.query" label="¿Qué te gustaría hacer?" clearable class="search-main"/><q-select outlined v-model="filter.categoryId" :options="categories" option-value="id" option-label="name" emit-value map-options clearable label="Categoría"/><q-input outlined v-model="filter.city" label="Ciudad"/><q-btn type="submit" color="primary" unelevated no-caps label="Buscar eventos" :loading="busy"/>
 <q-input outlined type="date" v-model="filter.from" label="Desde" stack-label/><q-input outlined type="date" v-model="filter.to" label="Hasta" stack-label/><q-btn flat no-caps label="Limpiar filtros" @click="clear"/></q-form>
 <div class="section-title"><div><div class="eyebrow">ELIGE TU EXPERIENCIA</div><h2>Descubre eventos</h2></div><span>Página {{page}}</span></div>
 <q-banner v-if="error" class="error" role="alert">{{error}} <q-btn flat label="Reintentar" @click="search()"/></q-banner><div v-if="busy" class="empty"><q-spinner size="36px" color="primary"/> Buscando eventos…</div>
 <div v-else-if="!events.length&&!error" class="empty"><h3>No hay eventos para estos filtros</h3><p>Prueba otra ciudad, categoría o fecha.</p><q-btn flat label="Limpiar filtros" @click="clear"/></div>
 <div v-else class="event-grid"><router-link v-for="(event,index) in events" :key="event.id" :to="'/evento/'+event.id" class="event-card"><div class="event-cover" :class="'cover-'+index%4"><span>{{event.category}}</span><strong>{{event.name.slice(0,1)}}</strong></div><div class="event-info"><small>{{date(event.startDate)}}</small><h3>{{event.name}}</h3><p>{{event.city}} · {{event.venue||event.address}}</p><div class="event-bottom"><strong>{{event.price===0?'Gratis':money(event.price,event.currency)}}</strong><q-badge :color="event.availableSpots>0?'primary':'grey'">{{event.availableSpots>0?'Ver evento':'Agotado'}}</q-badge></div></div></router-link></div>
 <div class="pagination"><q-btn flat no-caps label="Anterior" :disable="page===1||busy" @click="move(-1)"/><q-btn flat no-caps label="Siguiente" :disable="!next||busy" @click="move(1)"/></div></main></q-page></template>
